using System.Text.Json;
using System.Threading;
namespace CombatSolver;
internal static class TaskShuffleReadProbe
{
    private static long _snapshots, _cards, _key, _value, _either, _keyCards, _valueCards, _eitherCards;
    private static long _lateKey, _lateValue, _firstLateKey, _firstLateValue, _keyReads, _valueReads;
    static TaskShuffleReadProbe()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            string path = Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_SHUFFLE_READ_OUT")
                ?? throw new InvalidOperationException("missing task output");
            File.WriteAllText(path, JsonSerializer.Serialize(new {
                snapshots = _snapshots, cards = _cards, keyUsed = _key, valueUsed = _value,
                eitherUsed = _either, keyCardUnits = _keyCards, valueCardUnits = _valueCards,
                eitherCardUnits = _eitherCards, keyReads = _keyReads, valueReads = _valueReads,
                keyAfterRelease = _lateKey, valueAfterRelease = _lateValue,
                firstKeyAfterRelease = _firstLateKey, firstValueAfterRelease = _firstLateValue,
                scope = "read-only census; original eager calculation always executes; not performance"
            }, new JsonSerializerOptions { WriteIndented = true }));
        };
    }
    internal static int Created(int cards)
    {
        Interlocked.Increment(ref _snapshots); Interlocked.Add(ref _cards, cards); return 0;
    }
    internal static void Read(ref int flags, int bit, int cards, bool released)
    {
        int previous = Interlocked.Or(ref flags, bit);
        if (bit == 1)
        {
            Interlocked.Increment(ref _keyReads);
            if (released) Interlocked.Increment(ref _lateKey);
            if ((previous & 1) == 0) {
                Interlocked.Increment(ref _key); Interlocked.Add(ref _keyCards, cards);
                if (released) Interlocked.Increment(ref _firstLateKey);
            }
        }
        else
        {
            Interlocked.Increment(ref _valueReads);
            if (released) Interlocked.Increment(ref _lateValue);
            if ((previous & 2) == 0) {
                Interlocked.Increment(ref _value); Interlocked.Add(ref _valueCards, cards);
                if (released) Interlocked.Increment(ref _firstLateValue);
            }
        }
        if (previous == 0) {
            Interlocked.Increment(ref _either); Interlocked.Add(ref _eitherCards, cards);
        }
    }
}

